import 'package:flutter/material.dart';
import 'package:provider/provider.dart';
import '../../viewmodels/tutor_view_model.dart';
import '../../theme/app_theme.dart';

class TutorAvailabilityScreen extends StatefulWidget {const TutorAvailabilityScreen({super.key});@override State<TutorAvailabilityScreen> createState()=>_TutorAvailabilityScreenState();}
class _TutorAvailabilityScreenState extends State<TutorAvailabilityScreen>{static const days=['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'];late Set<String> selected;TimeOfDay start=const TimeOfDay(hour:9,minute:0),end=const TimeOfDay(hour:17,minute:0);bool initialized=false;
@override Widget build(BuildContext context){final vm=context.watch<TutorViewModel>();if(vm.isReady&&!initialized){selected=vm.workspace.availableDays.toSet();start=_parse(vm.workspace.startTime);end=_parse(vm.workspace.endTime);initialized=true;}return Scaffold(appBar:AppBar(title:const Text('Availability')),body:!vm.isReady?const Center(child:CircularProgressIndicator()):ListView(padding:const EdgeInsets.all(20),children:[const Text('Choose the days you are available for tutoring.',style:TextStyle(fontSize:16,fontWeight:FontWeight.w600)),const SizedBox(height:12),...days.map((d)=>CheckboxListTile(contentPadding:EdgeInsets.zero,title:Text(d),value:selected.contains(d),activeColor:AppColors.blue,onChanged:(v)=>setState(()=>v==true?selected.add(d):selected.remove(d))),),const Divider(height:28),_timeTile('Available from',start,(v)=>setState(()=>start=v)),_timeTile('Available until',end,(v)=>setState(()=>end=v)),const SizedBox(height:24),FilledButton.icon(onPressed:()async{if(selected.isEmpty){ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Select at least one day.')));return;}if(_minutes(end)<=_minutes(start)){ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('End time must be after start time.')));return;}await context.read<TutorViewModel>().updateAvailability(days:selected.toList(),start:_format(start),end:_format(end));if(context.mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Availability saved on this device.')));},icon:const Icon(Icons.save),label:const Text('Save availability'))]));}
Widget _timeTile(String label,TimeOfDay value,ValueChanged<TimeOfDay> onChanged)=>ListTile(contentPadding:EdgeInsets.zero,title:Text(label),subtitle:Text(value.format(context)),trailing:const Icon(Icons.access_time,color:AppColors.blue),onTap:()async{final picked=await showTimePicker(context:context,initialTime:value);if(picked!=null)onChanged(picked);});
TimeOfDay _parse(String s){final p=s.split(':');return TimeOfDay(hour:int.tryParse(p[0])??9,minute:int.tryParse(p[1])??0);}String _format(TimeOfDay t)=>'${t.hour.toString().padLeft(2,'0')}:${t.minute.toString().padLeft(2,'0')}';int _minutes(TimeOfDay t)=>t.hour*60+t.minute;}
